import React, { useState } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Sidebar from './components/Sidebar';
import HeaderBar from './components/HeaderBar';
import DashboardPage from './pages/DashboardPage';
import PlantHierarchyPage from './pages/PlantHierarchyPage';
import AssetListPage from './pages/AssetListPage';
import AddAssetPage from './pages/AddAssetPage';
import EditAssetPage from './pages/EditAssetPage';

function App() {
  const [selectedPlant, setSelectedPlant] = useState('All');

  return (
    <Router>
      <div className="app-layout">
        {/* Left Sidebar Navigation */}
        <Sidebar />

        {/* Main Workspace Wrapper */}
        <div className="main-wrapper">
          {/* Top Utility HeaderBar */}
          <HeaderBar selectedPlant={selectedPlant} onPlantChange={setSelectedPlant} />

          <main className="main-content">
            <Routes>
              <Route path="/" element={<DashboardPage />} />
              <Route path="/plants" element={<PlantHierarchyPage />} />
              <Route path="/assets" element={<AssetListPage selectedPlant={selectedPlant} />} />
              <Route path="/assets/new" element={<AddAssetPage />} />
              <Route path="/assets/edit/:id" element={<EditAssetPage />} />
              <Route path="*" element={<DashboardPage />} />
            </Routes>
          </main>
        </div>
      </div>
    </Router>
  );
}

export default App;
